examples.code:
#include <mdspan>
#include <array>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using E = std::extents<std::size_t, 2, std::dynamic_extent>;
    E extents{3};
    assert(
        extents.rank() == 2 && extents.rank_dynamic() == 1 && extents.extent(1) == 3);
    std::extents deduced{2, 3};
    assert(deduced.extent(0) == 2);
    assert(extents == E{3});
    std::layout_right::mapping<E> right{extents}, rightCopy{extents};
    assert(right == rightCopy);
    std::layout_left::mapping<E> left{extents}, leftCopy{extents};
    assert(left == leftCopy);
    std::layout_stride::mapping<E> stride{extents, std::array<std::size_t, 2>{3, 1}},
        strideCopy{extents, std::array<std::size_t, 2>{3, 1}};
    assert(stride == strideCopy);
    assert(right(1, 2) == 5 && left(1, 2) == 5 && stride(1, 2) == 5);
    assert(right.required_span_size() == 6 && left.required_span_size() == 6 &&
        stride.required_span_size() == 6);
    assert(right.extents() == extents && left.extents() == extents &&
        stride.extents() == extents);
    assert(right.stride(1) == 1 && left.stride(0) == 1 && stride.strides()[0] == 3);
    assert(right.is_unique() && right.is_exhaustive() && right.is_strided());
    assert(left.is_unique() && left.is_exhaustive() && left.is_strided());
    assert(stride.is_unique() && stride.is_exhaustive() && stride.is_strided());
    static_assert(decltype(right)::is_always_unique() &&
        decltype(right)::is_always_exhaustive() &&
        decltype(right)::is_always_strided());
    static_assert(decltype(left)::is_always_unique() &&
        decltype(left)::is_always_exhaustive() && decltype(left)::is_always_strided());
    static_assert(
        decltype(stride)::is_always_unique() && decltype(stride)::is_always_strided());
    int values[]{1, 2, 3, 4, 5, 6};
    std::mdspan<int, E> matrix{values, extents};
    assert((matrix[1, 2] == 6));
    assert(matrix.data_handle() == values && matrix.extents() == extents);
    assert(!matrix.empty() && matrix.size() == 6 && matrix.rank() == 2 &&
        matrix.rank_dynamic() == 1);
    assert(
        matrix.static_extent(0) == 2 && matrix.extent(1) == 3 && matrix.stride(1) == 1);
    assert(matrix.mapping()(1, 2) == 5 && matrix.accessor().access(values, 0) == 1);
    assert(matrix.is_unique() && matrix.is_exhaustive() && matrix.is_strided());
    std::default_accessor<int> accessor;
    assert(accessor.offset(values, 1) == values + 1);
    auto copy = matrix;
    copy = matrix;
    std::swap(copy, matrix);
    std::mdspan deducedMatrix{values};
    assert(deducedMatrix.extent(0) == 6);
    // extents construction/indexing exercises its private dynamic-index and product
    // helpers; these names are exposition-only.
}
